// Mimics a published package that wraps `next/image` (e.g. `next-cloudinary`).
// Because it is required from `node_modules` at runtime rather than bundled,
// it gets the on-disk copy of `next/image`, where `process.env.__NEXT_IMAGE_OPTS`
// was never inlined and the image config comes from `ImageConfigContext`.
const React = require('react')
const Image = require('next/image').default

function ExternalImage(props) {
  return React.createElement(Image, props)
}

module.exports = { ExternalImage }
